def add_images(self, names):
    # WonderMaker: side by side, as wide as the screen allows. A missing or broken picture is left out.
    import os
    import re
    from gi.repository import GdkPixbuf
    folder = os.path.join(os.path.dirname(os.path.dirname(os.path.dirname(os.path.abspath(__file__)))), "wm_images")
    names = [n for n in names if re.match(r"^[a-z0-9][a-z0-9-]{0,40}$", n)][:4]
    files = [f for f in (os.path.join(folder, n + ".png") for n in names) if os.path.isfile(f)]
    if not files:
        return
    width = max(120, min(300, (self.screen.width - 90 - 8 * (len(files) - 1)) // len(files)))
    row = Gtk.Box(orientation=Gtk.Orientation.HORIZONTAL, spacing=8, halign=Gtk.Align.CENTER)
    for f in files:
        try:
            row.add(Gtk.Image.new_from_pixbuf(GdkPixbuf.Pixbuf.new_from_file_at_scale(f, width, -1, True)))
        except Exception as e:
            logging.error(f"WonderMaker: picture {f} not shown: {e}")
    self.scroll_box.add(row)

