def wm_mark(self, params):
    # WonderMaker: two windows have too many step buttons for a small screen and get their own page, built like
    # the Move page: the adjust window of the tool setter position helper (buttons call _WM_SETTER_STEP ->
    # panels/wm_setter.py) and the Z trim windows (buttons call _WM_Z_TRIM_WIN / _WM_Z_TRIM_STEP ->
    # panels/wm_ztrim.py). The Z trim windows show the saved values on their buttons ("T0  +0.05",
    # "T0 trim now   +0.05 mm"); they are passed to the page.
    import re
    gcode = params[1].strip() if len(params) > 1 else ""
    if gcode.startswith("_WM_SETTER_STEP"):
        self.wm_target = ("wm_setter", "Tool setter position")
    elif gcode.startswith(("_WM_Z_TRIM_WIN", "_WM_Z_TRIM_STEP")):
        self.wm_target = ("wm_ztrim", "Z trim")
        if not hasattr(self, "wm_ztrim"):
            self.wm_ztrim = {"values": {}, "target": None}
        m = re.match(r"^\s*T([0-3])\s+(?:trim now\s+)?([-+]\d*\.?\d+)", params[0])
        if m:
            self.wm_ztrim["values"][int(m.group(1))] = float(m.group(2))
            if "trim now" in params[0]:
                self.wm_ztrim["target"] = int(m.group(1))

def wm_show_page(self):
    # WonderMaker: open (or refresh) the page of a marked window with its data. False: no page, show the window.
    target = getattr(self, "wm_target", None)
    if not target:
        return False
    page, title = target
    data = self.text if page == "wm_setter" else getattr(self, "wm_ztrim", None)
    scr = self.screen
    try:
        setattr(scr, page + "_data", data)
        if scr._cur_panels and scr._cur_panels[-1] == page:
            scr.panels[page].wm_refresh(data)
        else:
            scr.show_panel(page, title=title)
        if not (scr._cur_panels and scr._cur_panels[-1] == page):
            raise RuntimeError("page not shown")
        scr.screensaver.close()
        self.end()
        return True
    except Exception as e:
        logging.error(f"WonderMaker: page {page} not opened ({e}), window shown")
        self.wm_target = None
        return False

